class Product {
  constructor(public name: string, public price: number) {}
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}

class Order {
  id: number;
  items: any[];
  constructor(id: number, items: any[]) { this.id = id; this.items = items; }
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}

// Version A
class Shape {
  constructor(public type: string, public props: any) {}
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}

// Version B
class ShapeFactory {
  static create(shape: Shape) {
    return new Shape(shape.type, JSON.parse(JSON.stringify(shape.props)));
  }
}
